/*
 * Types shared between the BPF programs and the Go loader.
 * The Go counterparts are generated by bpf2go (see ../gen.go).
 */
#ifndef __SHAWK_H
#define __SHAWK_H

#define TASK_COMM_LEN 16

/*
 * The command name given to sockets that the kernel itself opens and holds
 * (NFS, iSCSI, CIFS, Ceph, ...), with a cgroup id of zero, which no process
 * has. User space names their service after their port.
 */
#define KERNEL_COMM "~kernel"

/* Direction of a flow seen from the local host. */
enum shawk_flow_direction {
	DIR_OUT = 1, /* active open: the local process is the client */
	DIR_IN = 2,  /* passive open: the local process is the server */
};

/*
 * Which peers outside the internal ranges are folded (see fold_peer()):
 * none, those of incoming flows, or those of all flows.
 */
enum shawk_fold_mode {
	FOLD_NONE = 0,
	FOLD_IN = 1,
	FOLD_ALL = 2,
};

/* Flags of struct shawk_flow_key. */
#define KEY_FOLDED (1U << 0) /* raddr stands for all peers outside the internal ranges */

/*
 * flow_key identifies a bundled flow. Following the in-kernel flow
 * bundling method, the client's ephemeral port is dropped and all
 * connections/datagrams between the same pair of addresses to the same
 * service port are bundled into a single entry. The process identity
 * (cgroup and comm) is part of the key so that different clients on the
 * same host remain distinguishable. A folded key bundles the peers outside
 * the internal ranges too: its remote address is zero.
 */
struct shawk_flow_key {
	__u8 laddr[16];               /* local address (IPv4-mapped IPv6 for IPv4) */
	__u8 raddr[16];               /* remote address */
	__u64 cgroup_id;              /* cgroup v2 id of the local process */
	__u32 netns;                  /* network namespace inode number */
	__u16 port;                   /* service (listening) port */
	__u8 direction;               /* enum shawk_flow_direction */
	__u8 proto;                   /* IPPROTO_TCP or IPPROTO_UDP */
	char comm[TASK_COMM_LEN];     /* command name of the local process */
	__u8 flags;                   /* KEY_* */
	__u8 _pad[7];
};

/*
 * A prefix of internal_peers: an address range whose peers are kept
 * exact. IPv4 ranges are IPv4-mapped, so an IPv4 /n is a prefix of length
 * 96+n.
 */
struct shawk_peer_prefix {
	__u32 prefixlen;
	__u8 addr[16];
};

/*
 * Buckets of the handshake durations of TCP active opens. Their upper
 * bounds, inclusive, are 100 µs, 250 µs, 500 µs, 1 ms, 2.5 ms, 10 ms,
 * 50 ms, 250 ms, 1 s and 3 s (see hs_bucket()); the last bucket has none.
 * The histogram shawk.tcp.handshake of the agent has the same bounds.
 */
#define HS_BUCKETS 11

/*
 * Why a TCP active open failed, the error.type of the agent (see
 * fail_reason()). A failure without one of these reasons is counted in
 * conn_fails only: conn_fails minus the sum of fails is the reason _OTHER.
 */
enum shawk_fail_reason {
	FAIL_REFUSED = 0,     /* a reset or ICMP port unreachable */
	FAIL_TIMEOUT = 1,     /* no answer to any SYN */
	FAIL_UNREACHABLE = 2, /* ICMP unreachable or prohibited, no ARP/ND answer */
	FAIL_LOCAL = 3,       /* no SYN was built: no free local port, no buffer */
	FAIL_ABORTED = 4,     /* the application closed the socket first */
	FAIL_REASONS = 5,
};

struct shawk_flow_stats {
	__u64 bytes_sent;
	__u64 bytes_recv;
	__u64 rtt_sum_us;   /* sum of smoothed RTT samples (TCP) */
	__u64 hs_sum_us;    /* sum of the handshake durations of hs_buckets, in µs */
	__u32 conns;        /* TCP connections established in the interval */
	__u32 conn_fails;   /* TCP active opens that failed in the interval */
	__u32 open_conns;   /* TCP connections open at the end of the interval */
	__u32 msgs_sent;    /* UDP datagrams sent */
	__u32 msgs_recv;    /* UDP datagrams received */
	__u32 retrans;      /* TCP segments retransmitted */
	__u32 rtt_samples;  /* number of RTT samples */
	__u32 pid;          /* last observed process id */
	/*
	 * TCP active opens established in the interval by the duration of
	 * their handshake, from connect(2) to the SYN-ACK. Those without a
	 * duration (see handshake_done()) are counted in conns only.
	 */
	__u32 hs_buckets[HS_BUCKETS];
	/*
	 * SYNs retransmitted by the active opens counted in the interval, as
	 * connections or as failures.
	 */
	__u32 syn_retrans;
	__u32 fails[FAIL_REASONS]; /* failed active opens by reason */
};

enum shawk_iter_rec_type {
	REC_LISTENER = 1, /* a listening/bound socket (from iter/tcp, iter/udp) */
	REC_OWNER = 2,    /* the owner process of a listening socket (from iter/task_file) */
};

/* Record emitted by the socket iterators through the seq_file. */
struct shawk_iter_rec {
	__u8 addr[16];
	__u64 cgroup_id;
	__u32 netns;
	__u32 pid;
	__u16 port;
	__u8 type;
	__u8 proto;
	char comm[TASK_COMM_LEN];
	/*
	 * Of a listener: 1 if the kernel chose its port, i.e. the socket was
	 * not bound to a port (bind(2) to port 0, or listen(2) without bind).
	 */
	__u8 kernel_chosen;
	__u8 _pad[3];
	/*
	 * Inode of the socket, which tells apart a listener replaced by another
	 * on the same address; 0 for sockets of the kernel, which have no file.
	 * The first subflow of an MPTCP listener has the file of the MPTCP
	 * socket.
	 */
	__u64 ino;
};

#define CGROUP_PATH_LEN 512

/* A cgroup v2 created on the host, sent to user space through a ring buffer. */
struct shawk_cgroup_event {
	__u64 id;
	char path[CGROUP_PATH_LEN];
};

/*
 * A translation of addresses learned from conntrack (see shawk_ct_confirm):
 * the client connected to virtual:vport, and the backend at backend:bport
 * saw the connection from source, which is the client unless the host
 * replaced its address (SNAT). The ports of the client and of the source
 * are ephemeral and dropped, as in flows.
 */
struct shawk_xlat_key {
	__u8 client[16];  /* original source (IPv4-mapped IPv6 for IPv4) */
	__u8 virt[16];    /* original destination */
	__u8 source[16];  /* reply destination */
	__u8 backend[16]; /* reply source */
	__u32 netns;      /* network namespace of the conntrack entry */
	__u16 vport;      /* original destination port */
	__u16 bport;      /* reply source port */
	__u8 proto;       /* IPPROTO_TCP or IPPROTO_UDP */
	__u8 _pad[7];
};

struct shawk_xlat_stats {
	__u64 conns; /* entries confirmed since the key was added */
	__s64 live;  /* entries alive now that were seen confirmed */
	__u64 gen;   /* when the key was added, which tells it from a former one */
};

/* A conntrack entry counted in the live count of its translation. */
struct shawk_xlat_conn {
	struct shawk_xlat_key key;
	__u64 gen; /* shawk_xlat_stats.gen of the key it was counted in */
};

#endif /* __SHAWK_H */
